import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"T","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/t.md","filePath":"glossaire-a-z/t.md"}'),s={name:"glossaire-a-z/t.md"};function o(i,e,l,d,u,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="t" tabindex="-1">T <a class="header-anchor" href="#t" aria-label="Permalink to &quot;T&quot;">​</a></h1><h2 id="testnet-fr-reseau-de-test" tabindex="-1">Testnet (fr : Réseau de test) <a class="header-anchor" href="#testnet-fr-reseau-de-test" aria-label="Permalink to &quot;Testnet (fr : Réseau de test)&quot;">​</a></h2><p>Un réseau blockchain distinct utilisé pour l’expérimentation et le développement, sans valeur économique réelle. Cardano propose des réseaux de test sur lesquels les développeurs utilisent des ada de test (<em>test ada</em>, tADA) pour essayer des applications décentralisées (dApps), des transactions et des mises à niveau.</p><h2 id="token-fr-jeton" tabindex="-1">Token (fr : Jeton) <a class="header-anchor" href="#token-fr-jeton" aria-label="Permalink to &quot;Token (fr : Jeton)&quot;">​</a></h2><p>Une unité ou une représentation numérique de valeur enregistrée sur une blockchain.</p><h2 id="tokenization-fr-tokenisation" tabindex="-1">Tokenization (fr : Tokenisation) <a class="header-anchor" href="#tokenization-fr-tokenisation" aria-label="Permalink to &quot;Tokenization (fr : Tokenisation)&quot;">​</a></h2><p>Le processus consistant à représenter des actifs du monde réel ou des actifs numériques sous forme de jetons sur une blockchain.</p><h2 id="token-standard-fr-standard-de-jetons" tabindex="-1">Token Standard (fr : Standard de jetons) <a class="header-anchor" href="#token-standard-fr-standard-de-jetons" aria-label="Permalink to &quot;Token Standard (fr : Standard de jetons)&quot;">​</a></h2><p>Un ensemble de règles définissant le comportement des jetons sur une blockchain afin d’assurer leur compatibilité et leur interopérabilité.</p><h2 id="total-value-locked-tvl-fr-valeur-totale-verrouillee" tabindex="-1">Total Value Locked (TVL) (fr : Valeur totale verrouillée) <a class="header-anchor" href="#total-value-locked-tvl-fr-valeur-totale-verrouillee" aria-label="Permalink to &quot;Total Value Locked (TVL) (fr : Valeur totale verrouillée)&quot;">​</a></h2><p>Une mesure de la valeur totale des jetons engagés dans un protocole de finance décentralisée (DeFi).</p><h2 id="tps-transactions-per-second-fr-transactions-par-seconde" tabindex="-1">TPS (Transactions Per Second) (fr : Transactions par seconde) <a class="header-anchor" href="#tps-transactions-per-second-fr-transactions-par-seconde" aria-label="Permalink to &quot;TPS (Transactions Per Second) (fr : Transactions par seconde)&quot;">​</a></h2><p>Une mesure du débit d’une blockchain indiquant le nombre de transactions qu’elle peut traiter en une seconde. C’est une mesure courante, mais limitée, car elle ne tient pas compte de la complexité des transactions.</p><h2 id="transaction-fr-transaction" tabindex="-1">Transaction (fr : Transaction) <a class="header-anchor" href="#transaction-fr-transaction" aria-label="Permalink to &quot;Transaction (fr : Transaction)&quot;">​</a></h2><p>Un enregistrement d’un transfert de valeur ou de données soumis à une blockchain et validé par le réseau. Sur Cardano, les transactions suivent le modèle eUTXO et peuvent inclure des jetons, des métadonnées ou des interactions avec des contrats intelligents.</p><h2 id="transaction-fee-fr-frais-de-transaction" tabindex="-1">Transaction Fee (fr : Frais de transaction) <a class="header-anchor" href="#transaction-fee-fr-frais-de-transaction" aria-label="Permalink to &quot;Transaction Fee (fr : Frais de transaction)&quot;">​</a></h2><p>Les frais facturés pour soumettre une transaction. Sur Cardano, ils sont calculés à partir de la taille sérialisée de la transaction, exprimée en octets.</p><h2 id="treasury-fr-tresorerie" tabindex="-1">Treasury (fr : Trésorerie) <a class="header-anchor" href="#treasury-fr-tresorerie" aria-label="Permalink to &quot;Treasury (fr : Trésorerie)&quot;">​</a></h2><p>Un mécanisme de financement décentralisé intégré à la blockchain Cardano, sans autorité centrale de contrôle. Il vise à assurer la durabilité à long terme du réseau en finançant son développement continu, la recherche et les activités de son écosystème. L’utilisation des fonds est décidée collectivement par les détenteurs d’ada au moyen de la gouvernance sur chaîne. Project Catalyst est l’une des initiatives soutenues par la trésorerie.</p><h2 id="treasury-cut-fr-part-prelevee-pour-la-tresorerie" tabindex="-1">Treasury Cut (fr : Part prélevée pour la trésorerie) <a class="header-anchor" href="#treasury-cut-fr-part-prelevee-pour-la-tresorerie" aria-label="Permalink to &quot;Treasury Cut (fr : Part prélevée pour la trésorerie)&quot;">​</a></h2><p>Le paramètre du protocole, souvent désigné par la lettre grecque τ (<em>tau</em>), qui détermine quelle fraction des récompenses de chaque époque est transférée vers la trésorerie.</p><h2 id="treasury-donation-fr-don-a-la-tresorerie" tabindex="-1">Treasury Donation (fr : Don à la trésorerie) <a class="header-anchor" href="#treasury-donation-fr-don-a-la-tresorerie" aria-label="Permalink to &quot;Treasury Donation (fr : Don à la trésorerie)&quot;">​</a></h2><p>Une transaction qui envoie directement des ada à la trésorerie de Cardano, augmentant ainsi les fonds disponibles pour soutenir les initiatives de la communauté.</p><h2 id="treasury-withdrawal-fr-retrait-de-la-tresorerie" tabindex="-1">Treasury Withdrawal (fr : Retrait de la trésorerie) <a class="header-anchor" href="#treasury-withdrawal-fr-retrait-de-la-tresorerie" aria-label="Permalink to &quot;Treasury Withdrawal (fr : Retrait de la trésorerie)&quot;">​</a></h2><p>Une action de gouvernance définie par la CIP-1694 qui propose de retirer des fonds de la trésorerie sur chaîne et de les verser à un ou plusieurs bénéficiaires.</p>',25)])])}const h=a(s,[["render",o]]);export{f as __pageData,h as default};
